class TTLStateStore {
  constructor(ttlMs) {
    this.ttlMs = ttlMs;
    this.map = new Map();
  }
  processMessage(key, value, t) {
    this.map.set(key, { last: t, value });
  }
  commitOffsets(offsets) {
    // persist offsets
  }
  evictStaleStates(now) {
    for (const [k, v] of this.map.entries()) {
